function validate([hamsters]) {
  if (typeof hamsters !== 'string') return 'hamsters must be a string.';
  if (hamsters.length < 1 || hamsters.length > 100000) return 'hamsters needs 1 to 100000 characters.';
  if (!/^[H.]+$/.test(hamsters)) return "hamsters may contain only 'H' and '.'.";
  return null;
}

