function minimumBuckets(hamsters) {
  const n = hamsters.length;
  let buckets = 0;
  let i = 0;
  while (i < n) {
    if (hamsters[i] !== 'H') {
      i++;
    } else if (i + 1 < n && hamsters[i + 1] === '.') {
      buckets++;
      i += 3;
    } else if (i > 0 && hamsters[i - 1] === '.') {
      buckets++;
      i++;
    } else {
      return -1;
    }
  }
  return buckets;
}

