function minimumBuckets(hamsters) {
  const n = hamsters.length;
  const empty = [];
  for (let i = 0; i < n; i++) if (hamsters[i] === '.') empty.push(i);
  let best = -1;
  for (let mask = 0; mask < (1 << empty.length); mask++) {
    const has = new Array(n).fill(false);
    let used = 0;
    for (let b = 0; b < empty.length; b++) if (mask & (1 << b)) { has[empty[b]] = true; used++; }
    let ok = true;
    for (let i = 0; i < n; i++) {
      if (hamsters[i] === 'H' && !(i > 0 && has[i - 1]) && !(i + 1 < n && has[i + 1])) { ok = false; break; }
    }
    if (ok && (best === -1 || used < best)) best = used;
  }
  return best;
}

