function generate(rand, size) {
  // Pieces in which every hamster already has an empty neighbour; joining them keeps that true.
  const pieces = ['.', '.', 'H.', '.H', 'H.H', '.HH.', '..'];
  if (size === 'small') {
    const n = 1 + Math.floor(rand() * 12);
    if (rand() < 0.5) {
      let s = '';
      while (s.length < n) s += pieces[Math.floor(rand() * pieces.length)];
      return [s.slice(0, n)];
    }
    const p = 0.2 + rand() * 0.6;
    let s = '';
    for (let i = 0; i < n; i++) s += rand() < p ? 'H' : '.';
    return [s];
  }
  const limit = 9000 + Math.floor(rand() * 1000);
  let s = '';
  while (true) {
    const piece = pieces[Math.floor(rand() * pieces.length)];
    if (s.length + piece.length > limit) break;
    s += piece;
  }
  // Now and then, block one hamster so the answer is -1.
  if (rand() < 0.2) {
    const at = Math.floor(rand() * (s.length - 3));
    s = s.slice(0, at) + 'HHH' + s.slice(at + 3);
  }
  return [s];
}
